def backup(path):
    if os.path.exists(path):
        bak = path + ".bak"
        try:
            shutil.copy2(path, bak)
        except:
            try:
                with open(path, 'rb') as s, open(bak, 'wb') as d:
                    d.write(s.read())
            except:
                pass

def write_file(path, content):
    backup(path)
    d = os.path.dirname(path)
    if d and not os.path.exists(d):
        os.makedirs(d, exist_ok=True)
    with open(path, 'w', encoding='utf-8', newline='\n') as f:
        f.write(content)

def expand_env(s):
    pat = re.compile(r'\$\(([^)]+)\)')
    def repl(m):
        var = m.group(1).strip()
        if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', var):
            return os.environ.get(var, '')
        return m.group(0)
    return pat.sub(repl, s)

def parse_config(content):
    cfg = {}
    order = []
    lines = content.splitlines()
    i = 0
    while i < len(lines):
        raw = lines[i]
        if not raw.strip() or raw.strip().startswith('#'):
            i+=1
            continue
        if '=' not in raw:
            i+=1
            continue
        pos = raw.find('=')
        tag = raw[:pos].strip()
        val_part = raw[pos+1:]
        acc = [val_part.lstrip()]
        j = i
        # continuation check
        while True:
            last = acc[-1]
            if not last.rstrip().endswith('\\'):
                break
            j+=1
            if j >= len(lines):
                break
            acc.append(lines[j])
        full = "\n".join(acc)
        if tag not in cfg:
            order.append(tag)
        cfg[tag] = full
        i = j+1
    return cfg, order

DEFAULT_CFG, DEFAULT_ORDER = parse_config(DOXYFILE_FULL) if DOXYFILE_FULL else ({}, [])

def do_x(config_path, expand):
    prog = sys.argv[0]
    if config_path == '-':
        try:
            content = sys.stdin.read()
        except:
            content = ""
        fname = '-'
    else:
        if not config_path:
            config_path = 'Doxyfile'
        if not os.path.exists(config_path):
            print(get_help(prog), end='')
            print(f'error: configuration file {config_path} not found!', file=sys.stderr)
            sys.exit(1)
        try:
            with open(config_path, 'r', encoding='utf-8') as f:
                content = f.read()
        except:
            print(get_help(prog), end='')
            print(f'error: configuration file {config_path} not found!', file=sys.stderr)
            sys.exit(1)
        fname = config_path

    user_cfg, user_order = parse_config(content)
    header = f"# Difference with default Doxyfile {VERSION}"
    out_lines = [header]
    for tag in user_order:
        if tag not in DEFAULT_CFG:
            # find line number
            lines = content.splitlines()
            line_no = 1
            for idx, l in enumerate(lines):
                if not l.strip() or l.strip().startswith('#'):
                    continue
                if '=' in l:
                    t = l[:l.find('=')].strip()
                    if t == tag:
                        line_no = idx+1
                        break
            print(f"warning: ignoring unsupported tag '{tag}' at line {line_no}, file {fname}", file=sys.stderr)
            continue
        user_val = user_cfg[tag]
        if expand:
            user_val = expand_env(user_val)
        default_val = DEFAULT_CFG.get(tag, "")
        if user_val.strip() == default_val.strip():
            continue
        # format
        val_lines = user_val.split("\n")
        first = val_lines[0].lstrip()
        out_lines.append(f"{tag:<22} = {first}")
        for cont in val_lines[1:]:
            out_lines.append(cont)
    sys.stdout.write("\n".join(out_lines) + "\n")

