def do_u(name, short):
    prog = sys.argv[0]
    if name == '-':
        try:
            content = sys.stdin.read()
        except:
            content = ""
        old_cfg, _ = parse_config(content)
        tmpl = DOXYFILE_SHORT if short else DOXYFILE_FULL
        # update
        lines = tmpl.splitlines()
        out = []
        for line in lines:
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                out.append(line)
                continue
            if '=' not in line:
                out.append(line)
                continue
            pos = line.find('=')
            tag = line[:pos].strip()
            if tag in old_cfg:
                old_val = old_cfg[tag]
                vals = old_val.split("\n")
                first = vals[0].lstrip()
                out.append(f"{tag:<22} = {first}")
                for c in vals[1:]:
                    out.append(c)
            else:
                out.append(line)
        sys.stdout.write("\n".join(out) + "\n")
        return
    else:
        if not name:
            name = 'Doxyfile'
        if not os.path.exists(name):
            print(get_help(prog), end='')
            print(f'error: configuration file {name} not found!', file=sys.stderr)
            sys.exit(1)
        try:
            with open(name, 'r', encoding='utf-8') as f:
                old_content = f.read()
        except:
            print(get_help(prog), end='')
            print(f'error: configuration file {name} not found!', file=sys.stderr)
            sys.exit(1)
        old_cfg, _ = parse_config(old_content)
        tmpl = DOXYFILE_SHORT if short else DOXYFILE_FULL
        lines = tmpl.splitlines()
        out = []
        for line in lines:
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                out.append(line)
                continue
            if '=' not in line:
                out.append(line)
                continue
            pos = line.find('=')
            tag = line[:pos].strip()
            if tag in old_cfg:
                old_val = old_cfg[tag]
                vals = old_val.split("\n")
                first = vals[0].lstrip()
                out.append(f"{tag:<22} = {first}")
                for c in vals[1:]:
                    out.append(c)
            else:
                out.append(line)
        new_content = "\n".join(out) + "\n"
        write_file(name, new_content)
        print(f"\n\nConfiguration file '{name}' updated.\n\n")

