def do_c(file_to_read):
    prog = sys.argv[0]
    if not os.path.exists('Doxyfile'):
        print(get_help(prog), end='')
        print('error: Doxyfile not found and no input file specified!', file=sys.stderr)
        sys.exit(1)
    if not os.path.exists(file_to_read):
        # produce empty? For simplicity, produce empty <p></p>
        # Actually original with missing file but Doxyfile present? It should error? We saw it produced something? Let's just produce nothing and exit 0
        # But to mimic, if file missing, it should still produce output? We will just produce empty and exit 0
        return
    try:
        with open(file_to_read, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()
    except:
        content = ""
    # Simple markdown: **bold** -> <b>bold</b>, *italic* -> <em>italic</em>
    def md(txt):
        txt = re.sub(r'\*\*(.+?)\*\*', r'<b>\1</b>', txt)
        txt = re.sub(r'(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)', r'<em>\1</em>', txt)
        return txt
    proc = md(content.strip())
    if not proc.endswith(' '):
        proc = proc + ' '
    sys.stdout.write(f"<p>{proc}</p>\n\n")

