def main():
    prog = sys.argv[0]
    argv = sys.argv[1:]

    # Handle no args
    if not argv:
        do_docgen(None, {})
        return

    # We'll parse actions with first-strong wins

    # Define action list
    actions = []
    mods = {'quiet':False, 'unbuffered':False, 'symbol_map':False, 'short':False, 'debug':[]}
    s_pending = False

    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == '-s':
            s_pending = True
            mods['short'] = True
            i+=1
            continue
        elif tok == '-q':
            mods['quiet'] = True
            i+=1
            continue
        elif tok == '-b':
            mods['unbuffered'] = True
            i+=1
            continue
        elif tok == '-m':
            mods['symbol_map'] = True
            i+=1
            continue
        elif tok == '-d':
            # check next
            if i+1 >= len(argv):
                actions.append({'type':'devhelp','explicit':True})
                i+=1
                continue
